def _shell(title: str, active: str, body: str, extra_js: str = '') -> str:
    links = [
        ('dashboard','⌂','Dashboard','/admin'),
        ('imports','⇧','Import Center','/admin/imports'),
        ('review','▤','Review Center','/admin/review'),
        ('releases','◉','Releases','/admin/releases'),
        ('health','♡','Data Health','/admin/health'),
        ('derived','▦','CET Data Calculator','/admin/derived-data'),
        ('audit','◷','Audit Log','/admin/audit'),
        ('feedback','✦','Feedback','/admin/feedback'),
        ('resolver','⌁','Website Resolver','/admin/resolver'),
        ('rollback','↶','Rollback','/admin/releases'),
    ]
    nav=''.join(f'<a class="{"active" if active==k else ""}" href="{href}">{icon} &nbsp; {label}</a>' for k,icon,label,href in links)
    return f'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} - CET CAP Admin</title><style>{CSS}</style></head><body class="admin-locked">
<div id="adminTabLock" class="admin-tab-lock"><div class="admin-tab-lock-card"><h2>Admin panel already open</h2><p>This admin account is already active in another tab. Close the other admin tab, then retry here.</p><button type="button" onclick="window.__cetAdminTabRetry&&window.__cetAdminTabRetry()">Retry</button><small>For security, only one admin tab is allowed at a time.</small></div></div>
<aside class="side"><div class="brand"><div class="mark">╫</div><div><b>CET CAP PORTAL</b><span>Admin Panel</span></div></div><nav class="nav">{nav}</nav><div class="sidefoot">CET CAP Portal v1.0.0<br>Maharashtra Admissions System<br><span class="online">● System Online</span></div></aside>
<main class="main"><header class="top"><div></div><div class="user"><span class="avatar">S</span><b>Admin</b><button type="button" class="btn ghost admin-close-btn" onclick="cetAdminClose()">Close</button></div></header><section class="content">{body}</section></main><div id="toastbox" class="toastbox"></div>{extra_js}
</body></html>'''


def _common_js():
    return r'''<script>
const ADMIN_AUTH_KEY='cet-cap-admin-auth-v1';
if(sessionStorage.getItem(ADMIN_AUTH_KEY)!=='1'){
  window.location.replace('/admin/login');
  throw new Error('Admin login required for this browser tab.');
}
window.__cetAdminTabReady=false;
(function(){
  const TAB_KEY='cet-cap-admin-tab-id-v1';
  const body=document.body;
  const gate=document.getElementById('adminTabLock');
  let tabId=sessionStorage.getItem(TAB_KEY);
  if(!tabId){
    tabId=(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2));
    sessionStorage.setItem(TAB_KEY,tabId);
  }
  function showBlocked(){
    window.__cetAdminTabReady=false;
    body.classList.add('admin-locked');
    gate.classList.add('show');
  }
  function showReady(){
    window.__cetAdminTabReady=true;
    body.classList.remove('admin-locked');
    gate.classList.remove('show');
  }
  async function securityAlert(action){
    try{
      const m=document.cookie.match(/(?:^|; )cet_admin_csrf=([^;]+)/);
      if(!m)return;
      await fetch('/admin/api/security-event',{method:'POST',headers:{'X-CSRF-Token':decodeURIComponent(m[1]),'X-Admin-Client-ID':tabId,'Content-Type':'application/json'},body:JSON.stringify({action})});
    }catch(_){ }
  }
  function notifyOtherAdmin(action){
    const labels={ADMIN_LOGIN_ATTEMPT:'Security alert: someone attempted to sign in to the Admin Panel.',ADMIN_LOGIN_BLOCKED:'Security alert: another admin login was blocked because this Admin Panel is already active.',ADMIN_LOGIN_FAILED:'Security alert: a failed Admin Panel login attempt was recorded.',ADMIN_TAB_RETRY:'Security alert: someone pressed Retry on the Admin Panel lock screen.',ADMIN_UNAUTHORIZED:'Security alert: an unauthenticated Admin Panel access attempt was blocked.'};
    toast(labels[action]||'Security alert: an admin access attempt was detected.','err');
  }
  // Keep the security-alert cursor for this browser tab. A normal admin
  // navigation creates a new document, so an in-memory cursor would reset to
  // zero and replay old security events as fresh alerts on every page.
  const SECURITY_CURSOR_KEY='cet-cap-admin-security-cursor-v1';
  let securityAfter=Number(sessionStorage.getItem(SECURITY_CURSOR_KEY)||0);
  let securityReady=securityAfter>0;
  async function pollSecurityAlerts(){
    try{
      const r=await fetch('/admin/api/security-alerts?after='+securityAfter,{cache:'no-store'});
      if(!r.ok)return;
      const d=await r.json();
      if(!securityReady){
        securityAfter=Number(d.latest_id||securityAfter);
        sessionStorage.setItem(SECURITY_CURSOR_KEY,String(securityAfter));
        securityReady=true;
        return;
      }
      for(const x of (d.events||[])){
        securityAfter=Math.max(securityAfter,Number(x.id)||0);
        sessionStorage.setItem(SECURITY_CURSOR_KEY,String(securityAfter));
        notifyOtherAdmin(x.action);
      }
      securityAfter=Math.max(securityAfter,Number(d.latest_id||securityAfter));
      sessionStorage.setItem(SECURITY_CURSOR_KEY,String(securityAfter));
    }catch(_){ }
  }
  async function acquireServerLock(){
    try{
      const r=await fetch('/admin/api/admin-lock/acquire',{method:'POST',headers:Object.assign(csrfHeaders(),{'X-Admin-Client-ID':tabId}),cache:'no-store'});
      if(r.ok){showReady();return true;}
      if(r.status===409){showBlocked();return false;}
    }catch(_){ }
    // Keep the page usable during a transient network failure; the heartbeat
    // will enforce the server-side lock as soon as the connection recovers.
    showReady();
    return true;
  }
  window.__cetAdminTabRetry=function(){securityAlert('ADMIN_TAB_RETRY');return acquireServerLock()};
  async function serverHeartbeat(){
    try{
      const r=await fetch('/admin/api/admin-lock/heartbeat',{method:'POST',headers:Object.assign(csrfHeaders(),{'X-Admin-Client-ID':tabId}),cache:'no-store'});
      if(r.status===409){
        sessionStorage.removeItem(ADMIN_AUTH_KEY);
        showBlocked();
      }
    }catch(_){}
  }
  async function releaseServerLock(){
    try{
      await fetch('/admin/api/admin-lock/release',{method:'POST',headers:Object.assign(csrfHeaders(),{'X-Admin-Client-ID':tabId}),cache:'no-store',keepalive:true});
    }catch(_){ }
  }
  async function bootAdminLock(){
    const acquired=await acquireServerLock();
    if(!acquired)return;
    securityReady=false;
    pollSecurityAlerts();
    serverHeartbeat();
    setInterval(pollSecurityAlerts,5000);
    setInterval(serverHeartbeat,5000);
  }
  // Internal admin navigation keeps the same tab identity. Do not release
  // the server lock during that navigation, otherwise the next admin page can
  // race the keepalive release and briefly lock itself out.
  let internalNavigation=false;
  document.addEventListener('click',function(event){
    const link=event.target.closest('a[href]');
    if(!link)return;
    const href=link.getAttribute('href')||'';
    if(href.startsWith('/admin') && !link.target && !event.ctrlKey && !event.metaKey && !event.shiftKey && !event.altKey){
      internalNavigation=true;
    }
  },true);
  window.addEventListener('pagehide',function(){
    if(internalNavigation)return;
    // Actual tab/window exit: release immediately. keepalive lets the request
    // continue while the document is being unloaded.
    releaseServerLock();
  });
  window.addEventListener('pageshow',function(event){
    // Only reacquire for a bfcache restore. A normal page load already calls
    // bootAdminLock(), so doing it here would create a redundant request.
    if(event.persisted) acquireServerLock();
  });
  window.__cetAdminBootLock=bootAdminLock;
})();
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const csrfHeaders=(extra={})=>{const m=document.cookie.match(/(?:^|; )cet_admin_csrf=([^;]+)/);return Object.assign({'X-CSRF-Token':m?decodeURIComponent(m[1]):''},extra)};
if(window.__cetAdminBootLock) window.__cetAdminBootLock();
async function cetAdminClose(){
  if(!confirm('Close the admin panel? Choose OK to log out and close this session.')) return;
  try{ await fetch('/admin/logout',{method:'POST',headers:csrfHeaders()}); }catch(_){ }
  try{sessionStorage.removeItem(ADMIN_AUTH_KEY);sessionStorage.removeItem('cet-cap-admin-tab-id-v1')}catch(_){ }
  window.location='/admin/login';
}
function toast(msg,type=''){const d=document.createElement('div');d.className='toast '+type;d.textContent=msg;document.querySelector('#toastbox').appendChild(d);setTimeout(()=>d.remove(),3500)}
async function api(url,opts={}){if(!window.__cetAdminTabReady)throw new Error('Admin panel is already open in another tab.');const r=await fetch(url,opts);const raw=await r.text();let data=raw;try{data=raw?JSON.parse(raw):null}catch{}if(r.status===401){window.location='/admin/login';throw new Error('Admin session expired. Please sign in again.')}if(!r.ok)throw new Error(typeof data==='string'?data:(data?.detail||'Request failed'));return data}
function fmtTime(v){if(!v)return '—';const d=new Date(String(v).replace(' ','T')+'Z');if(Number.isNaN(d.getTime()))return esc(v);return d.toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}
function badge(s){const x=String(s||'').toUpperCase(),c=x.includes('REVIEW')?'red':x.includes('FAIL')||x.includes('QUARANT')?'red':x.includes('PUBLISH')||x.includes('COMPLETE')||x.includes('VALID')?'green':x.includes('STAGED')||x.includes('COMMIT')?'purple':x.includes('RECEIVED')||x.includes('EXTRACT')||x.includes('NORMAL')?'blue':x.includes('WARN')?'amber':'gray';const loading=['RECEIVED','IDENTIFIED','EXTRACTING','NORMALIZING','VALIDATING','COMPARING'].includes(x);const label=x==='COMMITTING'?'COMMITTED • READY TO PUBLISH':x==='CANDIDATE'?'UNVERIFIED':x.replaceAll('_',' ');return `<span class="status ${c}${loading?' loading':''}">${esc(label)}</span>`}
function countUp(el,to){const n=Number(to)||0,from=Number(el.dataset.value||0),start=performance.now(),dur=450;function tick(t){const p=Math.min(1,(t-start)/dur),e=1-Math.pow(1-p,3);el.textContent=Math.round(from+(n-from)*e).toLocaleString();if(p<1)requestAnimationFrame(tick)}el.dataset.value=n;requestAnimationFrame(tick)}
async function removeImport(id,btn){if(btn?.disabled)return;if(!confirm('Delete this import? The uploaded PDF and all uncommitted import data will be removed.'))return;try{if(btn)btn.disabled=true;await api('/admin/api/imports/'+id,{method:'DELETE',headers:csrfHeaders()});toast('Import deleted','ok');if(typeof load==='function')load()}catch(e){if(btn)btn.disabled=false;toast(e.message,'err')}}
async function retryImport(id,btn){if(btn?.disabled)return;if(!confirm('Retry processing this PDF?'))return;try{if(btn)btn.disabled=true;await api('/admin/api/imports/'+id+'/process',{method:'POST',headers:csrfHeaders()});toast('Processing restarted','ok');if(typeof load==='function')load()}catch(e){if(btn)btn.disabled=false;toast(e.message,'err')}}
async function cancelImport(id,btn){if(btn?.disabled)return;if(!confirm('Stop processing this PDF? The import will be marked Cancelled and can be retried later.'))return;try{if(btn)btn.disabled=true;await api('/admin/api/imports/'+id+'/cancel',{method:'POST',headers:csrfHeaders()});toast('Processing stopped','ok');if(typeof load==='function')load()}catch(e){if(btn)btn.disabled=false;toast(e.message,'err')}}
async function toggleProcess(id,btn){const d=await api('/admin/api/imports/'+id);const s=String(d.job?.status||'');if(['RECEIVED','IDENTIFIED','EXTRACTING','NORMALIZING','VALIDATING','COMPARING'].includes(s)){await cancelImport(id,btn)}else if(s==='CANCELLED'||s==='FAILED'){await retryImport(id,btn)}else{toast('This import is not currently stoppable or retryable','err')}}
</script>'''


def dashboard() -> str:
    body='''<div class="title"><div><h1>Admin Dashboard</h1><p>Live overview of imports, processing, releases and data quality.</p></div><div class="live"><span class="dot"></span>Live · <span id="lastRefresh">updating</span></div></div>
<div class="cards"><div class="card kpi"><div class="khead"><span class="ki sky">⇧</span>Imports Today</div><div class="num" id="today">0</div><div class="trend up">Real-time import history</div></div><div class="card kpi"><div class="khead"><span class="ki rose">▤</span>Pending Review</div><div class="num" id="pending">0</div><div class="trend warn">Needs admin action</div></div><div class="card kpi"><div class="khead"><span class="ki mint">▣</span>Production Records</div><div class="num" id="production">0</div><div class="trend up">Published database rows</div></div><div class="card kpi"><div class="khead"><span class="ki lav">♡</span>Data Health</div><div class="num" id="health">—</div><div class="trend" id="healthHint">Checking runtime…</div></div></div>
<div class="card panel" style="margin-top:14px"><div class="toolbar"><h2>◌ &nbsp;Website Usage</h2><span class="muted small">last 30 days</span></div><div class="cards" style="grid-template-columns:repeat(4,1fr);margin-top:14px"><div class="card kpi"><div class="khead">Visitors</div><div class="num" id="siteVisitors">0</div></div><div class="card kpi"><div class="khead">Searches</div><div class="num" id="siteSearches">0</div></div><div class="card kpi"><div class="khead">College Opens</div><div class="num" id="siteCollegeOpens">0</div></div><div class="card kpi"><div class="khead">Website Clicks</div><div class="num" id="siteClicks">0</div></div></div><div id="siteUsageDetail" class="muted small" style="margin-top:12px">Collecting anonymous usage events…</div></div>
<div class="layout"><div><div class="card panel"><div class="toolbar"><h2>▤ &nbsp;Import Processing Pipeline</h2><span class="small muted" id="pipelineHint">Waiting for live data</span></div><div class="pipeline" id="pipeline"></div></div><div class="card panel recent"><div class="toolbar"><h2>☷ &nbsp;Recent Imports</h2><a class="muted" href="/admin/review">View All →</a></div><div class="tablewrap"><table class="table"><thead><tr><th>File</th><th>Year</th><th>Round</th><th>Type</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody id="rows"><tr><td colspan="7" class="skeleton">Loading</td></tr></tbody></table></div></div></div><div class="sidepanel"><div class="card panel"><div class="toolbar"><h2>▥ &nbsp;Recent Activity</h2><span class="muted small">last 7 days</span></div><div class="trendbox"><div class="bars" id="bars"></div><div class="muted" style="font-size:10px;text-align:center;padding-top:7px">Imports created per day</div></div></div><div class="card panel"><div class="toolbar"><h2>♡ &nbsp;System Health</h2><a class="muted" href="/admin/health">Details →</a></div><div id="healthList"></div></div></div></div>'''
    js=_common_js()+r'''<script>
const stages=['RECEIVED','SECURITY_CHECK','IDENTIFIED','EXTRACTING','NORMALIZING','VALIDATING','COMPARING','STAGED','REVIEW_REQUIRED','COMMITTING','PUBLISHING','VERIFYING','COMPLETED'];
function drawPipeline(jobs){const counts=Object.fromEntries(stages.map(s=>[s,0]));jobs.forEach(j=>{if(counts[j.status]!=null)counts[j.status]++});const active=jobs.find(j=>!['COMPLETED','QUARANTINED','FAILED','ROLLED_BACK'].includes(j.status))?.status;document.querySelector('#pipeline').innerHTML=stages.map((s,i)=>{let cls=active===s?'active':counts[s]?'done':'';if(s==='REVIEW_REQUIRED'&&counts[s])cls='review '+(active===s?'active':'');if(s==='COMPLETED')cls='publish '+cls;const label=s==='COMMITTING'?'Committed · Ready to Publish':s.replaceAll('_',' ');return `<div class="stage ${cls}"><div class="si">${s==='REVIEW_REQUIRED'?'!':s==='COMPLETED'?'✓':s==='VALIDATING'?'✓':'◉'}</div><b>${esc(label)}</b><small>${counts[s]||0}</small></div>`}).join('');document.querySelector('#pipelineHint').textContent=active?(active==='COMMITTING'?'Committed · Ready to Publish':`Processing: ${active.replaceAll('_',' ')}`):'No active processing';}
function drawBars(activity){const vals=Array.isArray(activity)?activity:[];const max=Math.max(1,...vals.map(v=>Number(v.count)||0));document.querySelector('#bars').innerHTML=vals.map(v=>{const h=Math.max(4,((Number(v.count)||0)/max)*100);return `<div class="barcol" title="${esc(v.label)}: ${Number(v.count)||0} import(s)"><div class="bar" style="height:${h}%"></div></div>`}).join('')||'<div class="empty" style="padding:20px">No import activity yet.</div>'}
async function load(){try{const [o,j]=await Promise.all([api('/admin/api/overview'),api('/admin/api/imports')]);countUp(document.querySelector('#today'),o.imports_today);countUp(document.querySelector('#pending'),o.pending_review);countUp(document.querySelector('#production'),o.production_rows);document.querySelector('#health').textContent=o.health.ok?'Healthy':'Check';document.querySelector('#healthHint').className='trend '+(o.health.ok?'up':'warn');document.querySelector('#healthHint').textContent=o.health.ok?'All runtime checks passing':'Attention required';document.querySelector('#lastRefresh').textContent=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});drawPipeline(j);drawBars(o.activity);document.querySelector('#rows').innerHTML=j.slice(0,8).map(x=>`<tr><td>📄 ${esc(x.original_filename)}</td><td>${esc(x.year||'—')}</td><td>${esc(x.round||'—')}</td><td>${esc(x.course_family||x.data_type||'—')}</td><td>${badge(x.status)}</td><td>${fmtTime(x.updated_at||x.created_at)}</td><td><div class="rowactions">${['RECEIVED','IDENTIFIED','EXTRACTING','NORMALIZING','VALIDATING','COMPARING'].includes(String(x.status||'').toUpperCase())?'<span class="activityspin" title="Processing" aria-label="Processing"></span>':''}${x.status==='FAILED'?'<button class="btn secondary" onclick="retryImport('+x.id+',this)">Retry</button>':''}<button class="trashbtn" title="Delete import" aria-label="Delete import" onclick="removeImport(${x.id},this)" ${['RECEIVED','IDENTIFIED','REVIEW_REQUIRED','STAGED','FAILED','CANCELLED','QUARANTINED'].includes(String(x.status||'').toUpperCase())?'':'disabled'}>🗑</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No imports yet.</td></tr>';document.querySelector('#healthList').innerHTML=[['Application',o.health.application],['Database',o.health.database],['File Storage',o.health.storage],['Site Build',o.health.site]].map(x=>`<div class="hr"><span class="hi">▣</span><span>${x[0]}</span><b class="${x[1]?'healthy':'danger'}">● ${x[1]?'Healthy':'Check'}</b></div>`).join('')}catch(e){toast(e.message,'err')}}window.refreshAdminData=load;load();setInterval(load,5000);
</script>'''
    return _shell('Admin Dashboard','dashboard',body,js)



def import_center() -> str:
    body='''<div class="title"><div><h1>Import Center</h1><p>Upload a CAP source PDF and track it through validation and review.</p></div><div class="live"><span class="dot"></span>Live queue</div></div><div class="pagegrid"><div class="card panel"><h2>Upload source PDF</h2><form id="uploadForm" style="margin-top:16px"><label class="notice" style="display:block;text-align:center;padding:35px;border:1px dashed #b9c6d6"><input id="file" type="file" accept="application/pdf" multiple required style="display:block;margin:auto auto 12px"><b>Select CAP PDFs</b><div class="small muted">Select multiple PDFs · uploaded and processed one at a time · Maximum 50 MiB each</div></label><div style="margin-top:12px"><button class="btn primary" id="uploadBtn">Upload All (1 at a time)</button></div></form><div id="uploadState" class="notice" style="margin-top:12px">Waiting for PDFs.</div><div id="uploadQueue" style="margin-top:12px"></div></div><div class="card panel"><h2>Import flow</h2><div class="timeline" style="margin-top:16px"><div class="event"><div class="eventdot"></div><div><h4>Receive</h4><p>Store and fingerprint the PDF.</p></div></div><div class="event"><div class="eventdot"></div><div><h4>Preflight</h4><p>Identify source metadata and validate safety.</p></div></div><div class="event"><div class="eventdot"></div><div><h4>Process</h4><p>Extract, normalize and stage records.</p></div></div><div class="event"><div class="eventdot"></div><div><h4>Review only on error</h4><p>Clean data stages automatically; validation findings go to Review Center.</p></div></div></div></div></div><div class="card panel" style="margin-top:14px"><div class="toolbar"><h2>Recent Imports</h2><button class="btn secondary" onclick="window.refreshAdminData()">↻ Refresh</button></div><div class="tablewrap"><table class="table"><thead><tr><th>File</th><th>Status</th><th>Metadata</th><th>Updated</th><th></th></tr></thead><tbody id="list"></tbody></table></div></div>'''
    js=_common_js()+r'''<script>
const form=document.querySelector('#uploadForm'),fileInput=document.querySelector('#file'),uploadBtn=document.querySelector('#uploadBtn'),state=document.querySelector('#uploadState'),queueEl=document.querySelector('#uploadQueue');
const MAX_UPLOAD=50*1024*1024;
let uploadQueue=[];
function renderUploadQueue(){queueEl.innerHTML=uploadQueue.map(function(x,i){return '<div class="notice" style="display:flex;justify-content:space-between;gap:10px;margin-top:6px;padding:9px 12px"><span><b>'+(i+1)+'. '+esc(x.file.name)+'</b><div class="small muted">'+(x.file.size/1048576).toFixed(1)+' MiB · '+esc(x.status||'Waiting')+'</div></span><span>'+(x.status==='Processing'?'⟳':x.status==='Done'?'✓':x.status==='Failed'?'✕':x.status==='Review required'?'!':'')+'</span></div>'}).join('');}
fileInput.addEventListener('change',function(){uploadQueue=[...fileInput.files].map(function(file){return {file:file,status:file.size>MAX_UPLOAD?'Too large':'Waiting'}});renderUploadQueue();state.textContent=uploadQueue.length?uploadQueue.filter(function(x){return x.status==='Waiting'}).length+' PDF(s) queued. They will upload one at a time.':'Waiting for PDFs.';});
async function waitForImport(id,index){const terminal=new Set(['COMMITTING','REVIEW_REQUIRED','FAILED','CANCELLED','QUARANTINED','ROLLED_BACK']);for(;;){const d=await api('/admin/api/imports');const j=d.find(function(x){return Number(x.id)===Number(id)});if(j&&terminal.has(String(j.status||'').toUpperCase()))return j;uploadQueue[index].status='Processing';renderUploadQueue();await new Promise(function(r){setTimeout(r,2000)})}}
form.addEventListener('submit',async function(e){e.preventDefault();if(!uploadQueue.length)return;const bad=uploadQueue.find(function(x){return x.status==='Too large'});if(bad){toast('One or more PDFs exceed the 50 MiB limit','err');return}uploadBtn.disabled=true;fileInput.disabled=true;try{for(let i=0;i<uploadQueue.length;i++){const item=uploadQueue[i];if(item.status!=='Waiting')continue;item.status='Uploading';state.textContent='Uploading '+(i+1)+' of '+uploadQueue.length+': '+item.file.name;renderUploadQueue();const h=new FormData();h.append('file',item.file);const r=await fetch('/admin/api/imports',{method:'POST',headers:csrfHeaders(),body:h});if(!r.ok){let msg=await r.text();try{msg=JSON.parse(msg).detail||msg}catch(_){ }throw new Error(msg)}const result=await r.json();item.status='Processing';renderUploadQueue();const done=await waitForImport(result.id,i);item.status=done.status==='FAILED'?'Failed':done.status==='REVIEW_REQUIRED'?'Review required':'Done';renderUploadQueue();state.textContent=(i+1)+' of '+uploadQueue.length+' finished: '+item.file.name;load()}toast('Batch upload finished — each PDF was processed one at a time','ok')}catch(err){const current=uploadQueue.find(function(x){return x.status==='Uploading'||x.status==='Processing'});if(current)current.status='Failed';renderUploadQueue();state.textContent='Batch stopped after an upload error. You can retry the remaining PDFs.';toast(err.message,'err')}finally{uploadBtn.disabled=false;fileInput.disabled=false;load()}});
async function removeImport(id,btn){if(btn?.disabled)return;if(!confirm('Delete this import? The uploaded PDF and all uncommitted import data will be removed.'))return;try{if(btn)btn.disabled=true;await api('/admin/api/imports/'+id,{method:'DELETE',headers:csrfHeaders()});toast('Import deleted','ok');load()}catch(e){if(btn)btn.disabled=false;toast(e.message,'err')}}async function retryImport(id,btn){if(btn?.disabled)return;if(!confirm('Retry processing this failed PDF?'))return;try{if(btn)btn.disabled=true;await api('/admin/api/imports/'+id+'/process',{method:'POST',headers:csrfHeaders()});toast('Retry started','ok');load()}catch(e){if(btn)btn.disabled=false;toast(e.message,'err')}}async function load(){try{const d=await api('/admin/api/imports');document.querySelector('#list').innerHTML=d.slice(0,20).map(x=>{const active=['RECEIVED','IDENTIFIED','EXTRACTING','NORMALIZING','VALIDATING','COMPARING'].includes(String(x.status||'').toUpperCase());return `<tr><td><b>${active?'<span class="pdfspin" aria-label="Processing"></span>':''}${esc(x.original_filename)}</b><div class="small muted">${esc(x.job_key)}</div></td><td>${badge(x.status)}</td><td>${esc([x.data_type,x.course_family,x.year,x.round].filter(Boolean).join(' · '))}</td><td>${fmtTime(x.updated_at||x.created_at)}</td><td><div class="rowactions">${active?'<span class="activityspin" title="Processing" aria-label="Processing"></span>':''}${x.status==='FAILED'?'<button class="btn secondary" onclick="retryImport('+x.id+',this)">Retry</button>':''}<button class="trashbtn" title="Delete import" aria-label="Delete import" onclick="removeImport(${x.id},this)" ${['RECEIVED','IDENTIFIED','REVIEW_REQUIRED','STAGED','FAILED','CANCELLED','QUARANTINED'].includes(String(x.status||'').toUpperCase())?'':'disabled'}>🗑</button></div></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No imports yet.</td></tr>'}catch(e){toast(e.message,'err')}}window.refreshAdminData=load;load();setInterval(load,5000);</script>'''
    return _shell('Import Center','imports',body,js)

def review_center() -> str:
    body='''<div class="title"><div><h1>Review Center</h1><p>Inspect staged records before they are committed to production.</p></div><div class="live"><span class="dot"></span>Auto-refresh · 5s</div></div>
<div class="grid4"><div class="card metric"><div class="label">Awaiting Review</div><div class="value" id="mReview">0</div></div><div class="card metric"><div class="label">Committing</div><div class="value" id="mCommit">0</div></div><div class="card metric"><div class="label">Staged Rows</div><div class="value" id="mRows">0</div></div><div class="card metric"><div class="label">Validation Issues</div><div class="value" id="mIssues">0</div></div></div>
<div class="card panel" style="margin-top:14px"><div class="toolbar"><div class="filters"><input id="q" class="input" placeholder="Search file, job, course…"><select id="status" class="select"><option value="">All statuses</option><option>REVIEW_REQUIRED</option><option>COMMITTING</option></select><select id="year" class="select"><option value="">All years</option></select></div><button class="btn secondary" onclick="window.refreshAdminData()">↻ Refresh</button></div><div class="tablewrap"><table class="table"><thead><tr><th>Import</th><th>Source</th><th>Metadata</th><th>Rows</th><th>Status</th><th>Updated</th><th>Action</th></tr></thead><tbody id="list"><tr><td colspan="7" class="skeleton">Loading</td></tr></tbody></table></div></div>
<div class="modalback" id="modal"><div class="modal"><div class="modalhead"><b id="modalTitle">Review Import</b><button class="close" onclick="closeModal()">×</button></div><div class="modalbody" id="modalBody"></div><div class="modalfoot" id="modalFoot"></div></div></div>'''
    js=_common_js()+r'''<script>
let jobs=[];const q=document.querySelector('#q'),st=document.querySelector('#status'),yr=document.querySelector('#year');[q,st,yr].forEach(x=>x.addEventListener('input',render));
async function load(){try{jobs=await api('/admin/api/review');const years=[...new Set(jobs.map(x=>x.year).filter(Boolean))].sort().reverse();yr.innerHTML='<option value="">All years</option>'+years.map(y=>`<option>${esc(y)}</option>`).join('');document.querySelector('#mReview').textContent=jobs.filter(x=>x.status==='REVIEW_REQUIRED').length;document.querySelector('#mCommit').textContent=jobs.filter(x=>x.status==='COMMITTING').length;document.querySelector('#mRows').textContent=jobs.reduce((n,d)=>n+Number(d.staging_row_count||0),0).toLocaleString();document.querySelector('#mIssues').textContent=jobs.reduce((n,d)=>n+Number(d.validation_issue_count||0),0).toLocaleString();render()}catch(e){toast(e.message,'err')}}
function render(){const term=q.value.trim().toLowerCase(),sv=st.value,yv=yr.value;const data=jobs.filter(x=>(!sv||x.status===sv)&&(!yv||String(x.year)===yv)&&(!term||[x.job_key,x.original_filename,x.course_family,x.data_type].some(v=>String(v||'').toLowerCase().includes(term))));document.querySelector('#list').innerHTML=data.map(x=>`<tr><td><b>${esc(x.job_key)}</b><div class="small muted">#${x.id}</div></td><td>${esc(x.original_filename)}</td><td>${esc([x.data_type,x.course_family,x.year,x.round].filter(Boolean).join(' · '))}</td><td>${esc(x.staging_row_count??'—')}</td><td>${badge(x.status)}</td><td>${fmtTime(x.updated_at||x.created_at)}</td><td><button class="btn primary" onclick="openReview(${x.id})">Review</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No imports match the current filters.</td></tr>'}
async function openReview(id){try{const d=await api('/admin/api/imports/'+id+'/review');const j=d.job;document.querySelector('#modalTitle').textContent=`${j.job_key} · Review`;const issue=(d.rows||[]).filter(r=>r.validation_status&&String(r.validation_status).toUpperCase()!=='VALID');document.querySelector('#modalBody').innerHTML=`<div class="grid4" style="grid-template-columns:repeat(3,1fr)"><div class="notice"><b>Source</b><br>${esc(j.original_filename)}</div><div class="notice"><b>Status</b><br>${badge(j.status)}</div><div class="notice"><b>Validation</b><br>${issue.length?issue.length+' issue(s)':'No issues reported'}</div></div><h3 style="font-size:13px;margin:20px 0 9px">Staged records (${d.rows?.length||0}${(d.rows?.length||0)>=500?'+':''})</h3>${issue.length?issue.slice(0,20).map(r=>`<div class="issue"><b>${esc(r.result_type||'Record')}</b> · page ${esc(r.source_page||'—')}<br>${esc(r.validation_message||r.validation_status)}</div>`).join(''):'<div class="issue good">All returned staged records are marked valid.</div>'}<details style="margin-top:12px"><summary>Raw staged JSON (first 10)</summary><pre class="json">${esc(JSON.stringify((d.rows||[]).slice(0,10),null,2))}</pre></details>`;document.querySelector('#modalFoot').innerHTML=j.status==='REVIEW_REQUIRED'?`<button class="btn dangerbtn" onclick="reject(${id})">Reject / Quarantine</button><button class="btn success" onclick="approve(${id})">Approve & Commit</button>`:'<button class="btn secondary" onclick="closeModal()">Close</button>';document.querySelector('#modal').classList.add('show')}catch(e){toast(e.message,'err')}}
function closeModal(){document.querySelector('#modal').classList.remove('show')}
async function approve(id){const notes=prompt('Approval note (optional):','');if(notes===null)return;try{await api('/admin/api/imports/'+id+'/approve',{method:'POST',headers:csrfHeaders({'Content-Type':'application/json'}),body:JSON.stringify({notes})});toast('Import approved and committed','ok');closeModal();load()}catch(e){toast(e.message,'err')}}
async function reject(id){const reason=prompt('Rejection reason (required):');if(!reason)return;try{await api('/admin/api/imports/'+id+'/reject',{method:'POST',headers:csrfHeaders({'Content-Type':'application/json'}),body:JSON.stringify({reason})});toast('Import quarantined','ok');closeModal();load()}catch(e){toast(e.message,'err')}}
window.refreshAdminData=load;load();setInterval(load,5000);
</script>'''
    return _shell('Review Center','review',body,js)


def releases_page() -> str:
    body='''<div class="title"><div><h1>Releases</h1><p>Build, verify, publish and roll back production data releases.</p></div><div class="live"><span class="dot"></span>Live state</div></div><div class="grid4"><div class="card metric"><div class="label">Total Releases</div><div class="value" id="total">0</div></div><div class="card metric"><div class="label">Published</div><div class="value" id="published">0</div></div><div class="card metric"><div class="label">Ready to Publish</div><div class="value" id="ready">0</div></div><div class="card metric"><div class="label">Latest Status</div><div class="value" id="latest" style="font-size:18px">—</div></div></div><div class="card panel" style="margin-top:14px"><div class="toolbar"><h2>Release History</h2><button class="btn secondary" onclick="window.refreshAdminData()">↻ Refresh</button></div><div class="tablewrap"><table class="table"><thead><tr><th>Release</th><th>Source Job</th><th>Status</th><th>Created</th><th>Published</th><th>Actions</th></tr></thead><tbody id="list"></tbody></table></div></div>'''
    js=_common_js()+r'''<script>
async function load(){try{const d=await api('/admin/api/releases');document.querySelector('#total').textContent=d.length;document.querySelector('#published').textContent=d.filter(x=>x.status==='PUBLISHED').length;document.querySelector('#ready').textContent=d.filter(x=>x.status==='COMMITTED').length;document.querySelector('#latest').textContent=d[0]?.status||'—';document.querySelector('#list').innerHTML=d.map(x=>`<tr><td><b>${esc(x.release_key)}</b><div class="small muted">#${x.id}</div></td><td>${esc(x.source_job_id)}</td><td>${badge(x.status)}</td><td>${fmtTime(x.created_at)}</td><td>${fmtTime(x.published_at)}</td><td>${x.status==='COMMITTED'?`<button class="btn primary" onclick="publish(${x.id})">Publish & Verify</button> <button class="btn dangerbtn" onclick="rollback(${x.id})">Revoke & Delete</button>`:x.status==='PUBLISHED'?`<button class="btn dangerbtn" onclick="rollback(${x.id})">Revoke & Delete</button>`:x.status==='ROLLED_BACK'?`<button class="btn dangerbtn" onclick="purge(${x.id})">Delete Permanently</button>`:'<span class="muted small">No action</span>'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No releases yet.</td></tr>'}catch(e){toast(e.message,'err')}}
async function publish(id){try{await api('/admin/api/releases/'+id+'/publish',{method:'POST',headers:csrfHeaders()});toast('Release published successfully','ok');load()}catch(e){toast(e.message,'err')}}
async function rollback(id){const reason=prompt('Revoke reason (required):');if(!reason)return;try{await api('/admin/api/releases/'+id+'/rollback',{method:'POST',headers:csrfHeaders({'Content-Type':'application/json'}),body:JSON.stringify({reason})});toast('Release revoked and production data deleted','ok');load()}catch(e){toast(e.message,'err')}} async function purge(id){try{await api('/admin/api/releases/'+id,{method:'DELETE',headers:csrfHeaders()});toast('Release and source import permanently deleted','ok');load()}catch(e){toast(e.message,'err')}}load();setInterval(load,8000);
</script>'''
    return _shell('Releases','releases',body,js)


def derived_data() -> str:
    body='''<div class="title"><div><h1>CET Data Calculator</h1><p>Manually calculate and store the precomputed data used by the public college drawer.</p></div><div class="live"><span class="dot"></span>Admin controlled</div></div>
<div class="pagegrid"><div class="card panel"><div class="toolbar"><h2>Build derived data</h2><span class="muted small">No automatic rebuilds</span></div>
<div class="notice">The source-of-truth tables remain untouched. This job only rebuilds the small runtime tables used by <b>graph/trend points, college category/quota options, and seat matrix</b>.</div>
<div class="filters" style="margin-top:14px"><select id="course" class="select"><option value="">All courses in production DB</option></select><button id="buildBtn" class="btn primary" onclick="startBuild()">▶ Calculate & Store</button></div>
<div class="notice" style="margin-top:12px">Run this when you are comfortable with the server load. While it runs, the public site continues using the last successfully built derived dataset.</div>
<div id="buildProgress" class="notice" style="margin-top:12px;display:none"><div style="display:flex;justify-content:space-between;gap:12px"><b id="progressTitle">Calculating…</b><span id="progressPct">0%</span></div><div style="height:10px;background:#e8edf3;border-radius:99px;overflow:hidden;margin-top:9px"><div id="progressBar" style="height:100%;width:0%;background:#11120D;transition:width .35s"></div></div><div id="progressMessage" class="small muted" style="margin-top:7px">Waiting for server…</div></div>
<div style="margin-top:18px"><div class="toolbar"><h2>Latest build</h2><span id="latestStatus" class="muted small">Loading…</span></div><div id="latest" class="notice">Loading build status…</div></div></div>
<div class="card panel"><div class="toolbar"><h2>What gets calculated</h2></div><div class="timeline"><div class="event"><div class="eventdot"></div><div><h4>Trend / graph points</h4><p>Per college, program, category, quota, year and CAP round.</p></div></div><div class="event"><div class="eventdot"></div><div><h4>Category & quota options</h4><p>Only combinations actually present for that particular college are stored.</p></div></div><div class="event"><div class="eventdot"></div><div><h4>Seat matrix</h4><p>Latest available seat matrix is reduced to the rows the drawer needs.</p></div></div><div class="event"><div class="eventdot"></div><div><h4>Public requests</h4><p>Fast indexed reads only. No heavy aggregation happens when candidates open Slide 2.</p></div></div></div></div></div>
<div class="card panel" style="margin-top:14px"><div class="toolbar"><h2>Build history</h2><button class="btn secondary" onclick="window.refreshAdminData()">↻ Refresh</button></div><div class="tablewrap"><table class="table"><thead><tr><th>ID</th><th>Course</th><th>Status</th><th>Progress</th><th>Message</th><th>Started</th><th>Finished</th><th>Actions</th></tr></thead><tbody id="history"></tbody></table></div></div>'''
    js=_common_js()+r'''<script>
let jobs=[];
const activeStates=['QUEUED','RUNNING'];
const terminalStates=['COMPLETED','FAILED','CANCELLED'];
function actionButtons(j){
  const s=String(j.status||'').toUpperCase();
  if(activeStates.includes(s)) return '<span class="small muted">Running…</span>';
  let out='';
  if(s==='FAILED'||s==='CANCELLED') out+='<button class="btn success" style="padding:6px 9px" onclick="retryBuild('+j.id+',this)">↻ Retry</button>';
  if(terminalStates.includes(s)) out+='<button class="trashbtn" title="Delete build history" aria-label="Delete build history" onclick="deleteBuild('+j.id+',this)">🗑</button>';
  return out||'<span class="small muted">—</span>';
}
async function load(){
  try{
    const d=await api('/admin/api/derived-data/status');jobs=d.jobs||[];
    const sel=document.querySelector('#course'),current=sel.value;
    sel.innerHTML='<option value="">All courses in production DB</option>'+d.courses.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('');
    if([...sel.options].some(o=>o.value===current))sel.value=current;
    const j=jobs[0],box=document.querySelector('#buildProgress');
    document.querySelector('#latestStatus').textContent=j?(j.status+' · '+j.progress+'%'):'No build yet';
    if(j){
      const pct=Math.max(0,Math.min(100,Number(j.progress)||0)),running=activeStates.includes(String(j.status).toUpperCase());
      box.style.display=running?'block':'none';document.querySelector('#progressTitle').textContent=running?'Calculating CET Data Calculator…':j.status;
      document.querySelector('#progressPct').textContent=Math.round(pct)+'%';document.querySelector('#progressBar').style.width=pct+'%';document.querySelector('#progressMessage').textContent=j.message||'';
      document.querySelector('#latest').innerHTML='<b>Build #'+j.id+'</b> · '+badge(j.status)+'<div style="margin-top:8px">'+esc(j.message||'—')+'</div>';
    }else{box.style.display='none';document.querySelector('#latest').textContent='No derived dataset has been built yet.'}
    const active=jobs.some(x=>activeStates.includes(String(x.status).toUpperCase()));document.querySelector('#buildBtn').disabled=active;
    document.querySelector('#history').innerHTML=jobs.map(x=>'<tr><td>#'+x.id+'</td><td>'+esc(x.course_family||'ALL')+'</td><td>'+badge(x.status)+'</td><td>'+esc(x.progress)+'%</td><td>'+esc(x.message||'—')+'</td><td>'+fmtTime(x.started_at)+'</td><td>'+fmtTime(x.finished_at)+'</td><td><span class="rowactions">'+actionButtons(x)+'</span></td></tr>').join('')||'<tr><td colspan="8" class="empty">No builds yet.</td></tr>';
  }catch(e){toast(e.message,'err')}
}
async function startBuild(){
  const course=document.querySelector('#course').value;

  try{document.querySelector('#buildBtn').disabled=true;const form=new FormData();if(course)form.append('course',course);await api('/admin/api/derived-data/build',{method:'POST',headers:csrfHeaders(),body:form});toast('Derived-data build started','ok');await load()}catch(e){toast(e.message,'err');await load()}
}
async function retryBuild(id,btn){
  if(btn.disabled)return;
  btn.disabled=true;const old=btn.textContent;btn.textContent='Retrying…';
  try{await api('/admin/api/derived-data/retry/'+id,{method:'POST',headers:csrfHeaders()});toast('Retry started','ok');await load()}catch(e){btn.disabled=false;btn.textContent=old;toast(e.message,'err')}
}
async function deleteBuild(id,btn){
  if(btn.disabled)return;
  btn.disabled=true;
  try{await api('/admin/api/derived-data/'+id,{method:'DELETE',headers:csrfHeaders()});toast('Build history deleted','ok');await load()}catch(e){btn.disabled=false;toast(e.message,'err')}
}
window.refreshAdminData=load;load();setInterval(load,3000);
</script>'''
    return _shell('CET Data Calculator','derived',body,js)


def health_page() -> str:
    body='''<div class="title"><div><h1>Data Health</h1><p>Live checks for the application, database, published site and production datasets.</p></div><div class="live"><span class="dot"></span>Continuous checks</div></div><div class="card panel" id="overall" style="margin-bottom:14px">Checking health…</div><div class="grid4" id="metrics"></div><div class="pagegrid" style="margin-top:14px"><div class="card panel"><div class="toolbar"><h2>Production Data</h2><span class="muted small" id="refreshAt">—</span></div><div class="tablewrap"><table class="table"><thead><tr><th>Dataset</th><th>Rows</th><th>State</th></tr></thead><tbody id="counts"></tbody></table></div></div><div class="card panel"><div class="toolbar"><h2>Detected Issues</h2></div><div id="issues"></div><h2 style="margin-top:20px">Latest Release</h2><div id="release" class="notice">—</div></div></div>'''
    js=_common_js()+r'''<script>
async function load(){try{const d=await api('/admin/api/health');const c=d.counts||{},r=d.runtime||{},ok=!!d.ok&&!!r.site_exists;document.querySelector('#overall').innerHTML=`<div style="display:flex;align-items:center;justify-content:space-between;gap:12px"><div><b style="font-size:18px">${ok?'System healthy':'Attention required'}</b><div class="small muted">${ok?'Core runtime checks are passing.':'One or more checks need attention.'}</div></div><span class="status ${ok?'green':'red'}">${ok?'HEALTHY':'CHECK'}</span></div>`;const names=[['Institutes','institutes'],['Programs','programs'],['Cutoffs','cutoffs'],['Seats','seats']];document.querySelector('#metrics').innerHTML=names.map(([n,k])=>`<div class="card metric"><div class="label">${n}</div><div class="value">${Number(c[k]||0).toLocaleString()}</div></div>`).join('');document.querySelector('#counts').innerHTML=Object.entries(c).map(([k,v])=>`<tr><td>${esc(k.replaceAll('_',' '))}</td><td><b>${Number(v).toLocaleString()}</b></td><td>${Number(v)>0||['audit_log','import_jobs'].includes(k)?badge('HEALTHY'):badge('EMPTY')}</td></tr>`).join('');const issues=[];if(!r.site_exists)issues.push('Published site directory is missing.');if(!r.latest_release)issues.push('No release has been created yet.');if((c.programs||0)===0)issues.push('Programs table is empty.');document.querySelector('#issues').innerHTML=issues.length?issues.map(x=>`<div class="issue">${esc(x)}</div>`).join(''):'<div class="issue good">No obvious data-health issues detected.</div>';document.querySelector('#release').innerHTML=r.latest_release?`<b>${esc(r.latest_release.release_key)}</b><br>${badge(r.latest_release.status)}<div class="small muted" style="margin-top:6px">Published: ${fmtTime(r.latest_release.published_at)} · Verified: ${fmtTime(r.latest_release.verified_at)}</div>`:'No releases yet';document.querySelector('#refreshAt').textContent='Updated '+new Date().toLocaleTimeString()}catch(e){toast(e.message,'err')}}window.refreshAdminData=load;load();setInterval(load,5000);
</script>'''
    return _shell('Data Health','health',body,js)


